from collections import deque

def gp(n,k):
 edges=set()
 for i in range(n):
  edges.add(tuple(sorted((i,(i+1)%n))))
  edges.add(tuple(sorted((i,n+i))))
  edges.add(tuple(sorted((n+i,n+((i+k)%n)))))
 return sorted(edges)

def girth(N,edges):
 adj=[[] for _ in range(N)]
 for u,v in edges:
  adj[u].append(v);adj[v].append(u)
 best=999
 for s in range(N):
  dist=[-1]*N;par=[-1]*N;q=deque([s]);dist[s]=0
  while q:
   u=q.popleft()
   for w in adj[u]:
    if dist[w]<0:
     dist[w]=dist[u]+1;par[w]=u;q.append(w)
    elif par[u]!=w and par[w]!=u:
     best=min(best,dist[u]+dist[w]+1)
 return best

def contract(N,edges,e):
 u,v=e
 # map v into u, vertices >v shift maybe normalize
 mapv={}
 idx=0
 for x in range(N):
  if x==v: continue
  mapv[x]=idx; idx+=1
 # but v maps to u's mapped value
 mapv[v]=mapv[u]
 new=set()
 for a,b in edges:
  aa=mapv[a];bb=mapv[b]
  if aa!=bb: new.add(tuple(sorted((aa,bb))))
 return idx,sorted(new)
